// Bottom padding matches this <li>'s box height to `.breadcrumb a`'s.
.breadcrumb-item-home {
  padding: 0 0 2.5px;
}

// Extends the link under the icon, so the shared `.breadcrumb-item a:hover`
// underline runs from the glyph's left edge (3.5px into the icon) to the text.
.breadcrumb-item-home a {
  padding-left: calc(1.35rem - 3.5px); // stylelint-disable-line function-disallowed-list
  margin-left: calc(3.5px - 1.35rem); // stylelint-disable-line function-disallowed-list
}
