// Deprecated styling for cards

// Deprecated custom classes: .card-clickable, .card-clickable-link
.card-clickable {
  border: {
    top-width: 0;
    right-width: 1px;
    bottom-width: 1px;
    left-width: 0;
    color: $rain;
  }

  .card-body {
    padding: 2.5rem;
    color: inherit;
    text-decoration: none;
  }

  .card-clickable-link {
    @extend .mb-0;
    color: $link-color;
  }

  &:hover {
    text-decoration: none;
  }
}

// Deprecated custom classes: .card-borderless, .card-clickable-link
.card-borderless {
  @extend .border-0;

  &:hover {
    .card-clickable-link {
      text-decoration: underline;
    }
  }
}

// Deprecated custom classes: .card-landing-grid, .landing-$color
.card-landing-grid {
  border-width: 2px 0 0 2px;
  box-shadow: 3px 3px 0 0 rgba($rain, .5);

  @each $color, $value in (map-remove($colors, "cloud", "caliche", "brick", "sage", "white", "black")) {
    // These classes are deprecated, so they keep the deprecated color names.
    $name: $color;
    @each $old, $new in $deprecated-color-names {
      @if $new == $color {
        $name: $old;
      }
    }
    &.landing-#{$name} {
      box-shadow: 3px 3px 0 0 rgba($value, .5);
    }
  }
}
